"""HTML document shell and SEO metadata."""
from .pages import *
def render(route,title,desc,content,og,index):
 actual='/' if route=='/404.html' else route
 fulltitle=title if route=='/' else title+' | Kodumi'; canonical=BASE+route
 schema={'@context':'https://schema.org','@type':'WebSite' if route=='/' else 'WebPage','name':fulltitle,'url':canonical,'description':desc}
 if route=='/':schema['publisher']={'@type':'Organization','name':'Kodumi','url':BASE+'/' ,'logo':BASE+'/assets/logo.svg'}
 ld=json.dumps(schema,ensure_ascii=False).replace('<','\\u003c')
 return f'''<!doctype html><html lang="ru" class="no-js"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{E(fulltitle)}</title><meta name="description" content="{E(desc)}"><meta name="robots" content="{'index,follow' if index else 'noindex,follow'}"><link rel="canonical" href="{E(canonical)}"><meta name="theme-color" content="#11162e"><meta property="og:type" content="website"><meta property="og:site_name" content="Kodumi"><meta property="og:title" content="{E(fulltitle)}"><meta property="og:description" content="{E(desc)}"><meta property="og:url" content="{E(canonical)}"><meta property="og:image" content="{E(BASE+'/'+og)}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{E(fulltitle)}"><meta name="twitter:description" content="{E(desc)}"><meta name="twitter:image" content="{E(BASE+'/'+og)}"><link rel="icon" href="{rel('/assets/logo.svg',actual)}" type="image/svg+xml"><link rel="stylesheet" href="{rel('/assets/site.css',actual)}"><script>document.documentElement.classList.replace('no-js','js')</script><script type="application/ld+json">{ld}</script><script src="{rel('/assets/site.js',actual)}" defer></script></head><body><a class="skip" href="#content">К содержанию</a><div id="route-progress" aria-hidden="true"></div>{header(actual)}<main id="content" tabindex="-1">{content}</main>{footer(actual)}</body></html>'''
